const { buildSkill } = require('../build-skill');

const NOTICE =
  '<!--\nAdapted from Plumeria documentation, https://plumeria.dev/docs/ai\nMIT\n-->';

const aiMd = (body) =>
  [
    '# AI.md',
    '',
    'Source: https://plumeria.dev/docs/ai',
    '',
    'Generated by `docs/scripts/generate-ai.mjs`. Do not edit this file directly.',
    'Adapted for TypedCSS.',
    '',
    'This document is for AI assistants.',
    '',
    body,
    NOTICE,
    '',
  ].join('\n');

test('replaces the preamble and anchors, and keeps the notice last', () => {
  const files = buildSkill(aiMd('## Rules [#rules]\n\n### Detail [#detail]\n'));
  const skill = files['SKILL.md'];
  expect(skill.startsWith('---\nname: typedcss\ndescription: ')).toBe(true);
  expect(skill).not.toContain('# AI.md');
  expect(skill).not.toContain('Source: ');
  expect(skill).toContain('This document is for AI assistants.');
  expect(skill).toContain('## Rules\n');
  expect(skill).toContain('### Detail\n');
  expect(skill).not.toContain('[#');
  expect(skill.endsWith(`${NOTICE}\n`)).toBe(true);
  expect(Object.keys(files)).toEqual(['SKILL.md']);
});

test('moves reference sections into their own files and indexes them', () => {
  const files = buildSkill(
    aiMd(
      [
        '## Rules [#rules]',
        '',
        '- Forward styles. (→ Styling Custom Components)',
        '- Pair them (see Advanced APIs).',
        '',
        '## Advanced APIs [#advanced-apis]',
        '',
        '```md',
        '## Not a heading',
        '```',
        '',
        '## Styling Custom Components [#styling-custom-components]',
        '',
        'Body.',
        '',
      ].join('\n'),
    ),
  );
  const skill = files['SKILL.md'];

  expect(skill).toContain('(→ references/custom-components.md)');
  expect(skill).toContain('(see references/advanced-apis.md)');
  expect(skill).not.toContain('## Advanced APIs');
  expect(skill).toContain('- `references/advanced-apis.md` — ');
  expect(skill).toContain('- `references/custom-components.md` — ');
  expect(files['references/advanced-apis.md']).toBe(
    '## Advanced APIs\n\n```md\n## Not a heading\n```\n',
  );
  expect(files['references/custom-components.md']).toBe(
    '## Styling Custom Components\n\nBody.\n',
  );
});
